  lines.push(JSON.stringify(rec));
  console.log("### "+c.id+" @ "+c.situation.date+(rec.situation_error?"  SITUATION_ERROR: "+rec.situation_error:"")+(rec.error?"  ERROR: "+rec.error:""));
